import test from 'node:test';import assert from 'node:assert/strict';import {bootstrapRequest} from './bootstrap-client.js';
const token='e'.repeat(64),body={target_id:'one',review_digest:'a'.repeat(64),request_id:'11111111-1111-4111-8111-111111111111',confirm_install:true,retry_unknown:false};
test('bootstrap submits only exact approved operation without credentials or commands',async()=>{let request;const op={...body,state:'unknown',attempts:1};const value=await bootstrapRequest(token,body,{fetcher:async(url,opts)=>{request={url,opts};return{ok:true,json:async()=>op}}});assert.equal(value.state,'unknown');assert.equal(request.url,'/admin/api/v1/bootstrap');assert.equal(request.opts.credentials,'omit');assert.equal(request.opts.redirect,'error');assert.deepEqual(JSON.parse(request.opts.body),body)});
test('bootstrap refuses missing explicit confirmation and changed response',async()=>{await assert.rejects(bootstrapRequest(token,{...body,confirm_install:false}),/Confirm/);await assert.rejects(bootstrapRequest(token,body,{fetcher:async()=>({ok:true,json:async()=>({...body,review_digest:'b'.repeat(64),state:'installed',attempts:1})})}),/Outcome unknown/)});
test('lost bootstrap reply never claims rollback',async()=>{await assert.rejects(bootstrapRequest(token,body,{fetcher:async()=>{throw Error('network')}}),/does not undo installation/)});
